    (FALSE, DATE '2001-11-11', 128, 51290, TIMESTAMP '2024-11-14 10:59:18.195841', 349, 999, TIMESTAMP '2024-11-14 10:59:18.195841', 0, U&'\c720\c815\ce60 (\c9c0\c740\c774)', 'https://image.aladin.co.kr/product/30/48/cover200/8978891179_2.jpg', '8978891179', U&'\c9c0\c131\c0ac', U&'\d55c\ac15\c5d0\c11c \b9cc\b098\b294 \c0c8\c640 \bb3c\ace0\ae30 - \d55c\ac15\b530\b77c \c0dd\d0dc\ae30\d589', NULL),
